  9310  static bool
  9311  wasm_loader_emit_br_info(WASMLoaderContext *ctx, BranchBlock *frame_csp,
  9312                           bool is_br, char *error_buf, uint32 error_buf_size)
  9313  {
  9314      /* br info layout:
  9315       *  a) arity of target block
  9316       *  b) total cell num of arity values
  9317       *  c) each arity value's cell num
  9318       *  d) each arity value's src frame offset
  9319       *  e) each arity values's dst dynamic offset
  9320       *  f) branch target address
  9321       *
  9322       *  Note: b-e are omitted when arity is 0 so that
  9323       *  interpreter can recover the br info quickly.
  9324       */
  9325      BlockType *block_type = &frame_csp->block_type;
  9326      uint8 *types = NULL, cell;
  9327  #if WASM_ENABLE_GC != 0
  9328      WASMRefTypeMap *reftype_maps;
  9329      uint32 reftype_map_count;
  9330  #endif
  9331      uint32 arity = 0;
  9332      int32 i;
  9333      int16 *frame_offset = ctx->frame_offset;
  9334      uint16 dynamic_offset;
  9335
  9336      /* Note: loop's arity is different from if and block. loop's arity is
  9337       * its parameter count while if and block arity is result count.
  9338       */
  9339  #if WASM_ENABLE_GC == 0
  9340      if (frame_csp->label_type == LABEL_TYPE_LOOP)
  9341          arity = block_type_get_param_types(block_type, &types);
  9342      else
  9343          arity = block_type_get_result_types(block_type, &types);
  9344  #else
  9345      if (frame_csp->label_type == LABEL_TYPE_LOOP)
  9346          arity = block_type_get_param_types(block_type, &types, &reftype_maps,
  9347                                             &reftype_map_count);
  9348      else
  9349          arity = block_type_get_result_types(block_type, &types, &reftype_maps,
  9350                                              &reftype_map_count);
  9351  #endif
  9352
  9353      /* Part a */
  9354      emit_uint32(ctx, arity);
  9355
  9356      if (arity) {
  9357          /* Part b */
  9358          emit_uint32(ctx, wasm_get_cell_num(types, arity));
  9359          /* Part c */
  9360          for (i = (int32)arity - 1; i >= 0; i--) {
  9361              cell = (uint8)wasm_value_type_cell_num(types[i]);
  9362              emit_byte(ctx, cell);
  9363          }
  9364          /* Part d */
  9365          for (i = (int32)arity - 1; i >= 0; i--) {
  9366              cell = (uint8)wasm_value_type_cell_num(types[i]);
  9367              frame_offset -= cell;
  9368              emit_operand(ctx, *(int16 *)(frame_offset));
  9369          }
  9370          /* Part e */
  9371          if (frame_csp->label_type == LABEL_TYPE_LOOP)
  9372              /* Use start_dynamic_offset which was set in
  9373                 copy_params_to_dynamic_space */
  9374              dynamic_offset = frame_csp->start_dynamic_offset
  9375                               + wasm_get_cell_num(types, arity);
  9376          else
  9377              dynamic_offset =
  9378                  frame_csp->dynamic_offset + wasm_get_cell_num(types, arity);
  9379          if (is_br)
  9380              ctx->dynamic_offset = dynamic_offset;
  9381          for (i = (int32)arity - 1; i >= 0; i--) {
  9382              cell = (uint8)wasm_value_type_cell_num(types[i]);
  9383              dynamic_offset -= cell;
  9384              emit_operand(ctx, dynamic_offset);
  9385          }
  9386      }
  9387
  9388      /* Part f */
  9389      if (frame_csp->label_type == LABEL_TYPE_LOOP) {
  9390          wasm_loader_emit_ptr(ctx, frame_csp->code_compiled);
  9391      }
  9392      else {
  9393          if (!add_label_patch_to_list(frame_csp, PATCH_END, ctx->p_code_compiled,
  9394                                       error_buf, error_buf_size))
  9395              return false;
  9396          /* label address, to be patched */
  9397          wasm_loader_emit_ptr(ctx, NULL);
  9398      }
  9399
  9400      return true;
